"""Private original-incidence tables for one logical junction boundary.

This binds topology only. Source curves, corners, cuts and separator noses are
computed by the shared native group. The initial branch supports at most one
internal span between consecutive external ports, and rejects longer chains.
"""
from .curved_junction_bindings import _mesh


def records(plan, compiled, cluster):
    source_sites = {s.junction_id: (i, s) for i, s in enumerate(plan.sites)}
    spans = {s.identity: i for i, s in enumerate(plan.spans)}
    ranges = {jid: (start, count) for jid, start, count in compiled.junction_ranges}
    local = {}; sites = []; count = 0
    for jid in cluster.physical_junction_ids:
        index, site = source_sites[jid]
        first, size = ranges[jid]
        if size != len(site.ports):
            raise ValueError('Original cluster port binding is stale')
        sites.append(dict(site=index, junction_id=jid, first=count, count=size))
        for at, port in enumerate(site.ports): local[port.endpoint] = count+at
        count += size
    links = []
    footprint_spans = set(cluster.footprint_spans)
    covered_footprints = set()
    for link in cluster.boundaries:
        if len(link.traversed_spans) > 1:
            raise ValueError('Native logical boundary supports one internal span per boundary link')
        if len(link.original_corners) != 1+len(link.traversed_spans):
            raise ValueError('Every original boundary corner must retain its source incidence')
        row = dict(a=local[link.start_port.endpoint], b=local[link.end_port.endpoint],
                   corner_a=local[link.original_corners[0].endpoint],
                   corner_b=local[link.original_corners[-1].endpoint], span=-1, mid_a=0, mid_b=0,
                   footprint=0)
        if link.traversed_spans:
            identity, start = link.traversed_spans[0]
            span = plan.spans[spans[identity]]
            end = span.end.endpoint if start == span.start.endpoint else span.start.endpoint
            row.update(span=spans[identity], mid_a=local[start], mid_b=local[end])
            if identity in footprint_spans:
                row['footprint'] = 1
                covered_footprints.add(identity)
        links.append(row)
    if covered_footprints != footprint_spans:
        raise ValueError('Every retained internal logical Street needs a native footprint check')
    return sites, links


def tables(plan, compiled, cluster, label):
    sites, links = records(plan, compiled, cluster)
    def table(name, rows):
        return _mesh(label+' private '+name, [(0.,0.,0.)]*len(rows), [], [
            ('st_lc_'+key, 'INT', 'POINT', [r[key] for r in rows]) for key in rows[0]])
    return {'Cluster Sites': table('logical sites', sites), 'Boundary Links': table('logical links', links)}


def network_tables(plan, compiled, clusters, label, join_radius, *, shared_logical=False):
    """Flat private ranges for many logical owners sharing the native root."""
    declarations=[]; sites=[]; links=[]; spans=[]; chain_links=[]; chain_steps=[]
    span_index={span.identity:i for i,span in enumerate(plan.spans)}
    for owner,cluster in enumerate(clusters):
        chain=len(cluster.owner_ids)>1
        if chain:
            if not shared_logical:raise ValueError('Shared logical owners need the chain-capable solver')
            from .curved_logical_chain_bindings import records as chain_records
            local_sites,program,steps=chain_records(plan,compiled,cluster)
            # The general registry needs original exterior incidences/counts.
            # Its old single-span fields are never consumed by this branch.
            local_links=[dict(a=r['a'],b=r['b'],corner_a=r['a'],corner_b=r['b'],
                span=-1,mid_a=0,mid_b=0,footprint=0) for r in program]
            chain_links.extend(dict(**r,cluster=owner) for r in program)
            chain_steps.extend(dict(**r,cluster=owner) for r in steps)
        else:local_sites,local_links=records(plan,compiled,cluster)
        declarations.append(dict(id=cluster.logical_junction_id,
            site=min(row['site'] for row in local_sites),site_start=len(sites),site_count=len(local_sites),
            link_start=len(links),link_count=len(local_links),join_radius=join_radius,chain=int(chain)))
        sites.extend(dict(**row,owner=owner) for row in local_sites)
        links.extend(dict(**row,owner=owner) for row in local_links)
        spans.extend(dict(span=span_index[span.identity],owner=owner) for span in cluster.internal_spans)
    def table(name,prefix,rows,keys):
        return _mesh(label+' private '+name,[(0.,0.,0.)]*len(rows),[],[
            (prefix+key,'FLOAT' if key=='join_radius' else 'INT','POINT',[row[key] for row in rows]) for key in keys])
    result = {
        'Logical Clusters':table('logical owners','st_lg_',declarations,
            ('id','site','site_start','site_count','link_start','link_count','join_radius')+ (('chain',) if shared_logical else ())),
        'Cluster Sites':table('logical sites','st_lc_',sites,('site','junction_id','first','count','owner')),
        'Boundary Links':table('logical links','st_lc_',links,('a','b','corner_a','corner_b','span','mid_a','mid_b','footprint','owner')),
        'Cluster Spans':table('logical spans','st_lc_',spans,('span','owner')),
    }
    if shared_logical:
        result['Chain Links']=table('chain links','st_lq_',chain_links,('a','b','first','count','cluster'))
        result['Chain Steps']=table('chain steps','st_lq_',chain_steps,
            ('owner','corner','span','mid_a','mid_b','footprint','cluster'))
    return result
